import{_ as s,o as i,c as a,ag as e}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetDO8421 设置8421码数字量输出","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/SetDO8421.md","filePath":"3. 指令/4. IO 指令/SetDO8421.md","lastUpdated":1778862643000}'),n={name:"3. 指令/4. IO 指令/SetDO8421.md"};function l(r,t,d,o,h,p){return i(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="setdo8421-设置8421码数字量输出" tabindex="-1">SetDO8421 设置8421码数字量输出 <a class="header-anchor" href="#setdo8421-设置8421码数字量输出" aria-label="Permalink to &quot;SetDO8421 设置8421码数字量输出&quot;">​</a></h1><p>该指令用于设置一段连续的数字量输出（DO）端口状态。它将传入的一个十进制数值转换成二进制数据，并按位分配到指定的连续 DO 端口上（起始端口对应二进制的最低位 LSB）。这通常用于向外部设备（如 PLC）发送多位编码、设置 BCD 码数值或批量控制一组输出。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>SetDO8421 (BEGINPORT, ENDPORT, SETVALUE)</code></p><p><code>SetDO8421 (起始端口, 结束端口, 设置值)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>BEGINPORT</td><td>int</td><td>该段连续数字量输出端口的起始端口号</td><td>必填</td></tr><tr><td>ENDPORT</td><td>int</td><td>该段连续数字量输出端口的结束端口号</td><td>必填</td></tr><tr><td>SETVALUE</td><td>int 或 INT 变量</td><td>需要设置的十进制目标值，系统将其转换为二进制按位赋值</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetDO8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li><strong>十进制值</strong>：255。</li><li><strong>二进制转换</strong>：255 转换为 8 位二进制数为 <code>1111 1111</code>。</li><li><strong>执行结果</strong>：将第 <strong>9</strong> 到第 <strong>16</strong> 号数字量输出端口全部置为 <strong>1</strong>（高电平）。</li></ol><p><strong>示例 2：设置特定编码</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetDO8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>：</p><ol><li><strong>十进制值</strong>：10。</li><li><strong>二进制转换</strong>：10 转换为 4 位二进制数为 <code>1010</code>。</li><li><strong>执行结果</strong>： <ul><li>1 号口（最低位）= 0</li><li>2 号口 = 1</li><li>3 号口 = 0</li><li>4 号口（最高位）= 1</li></ul></li></ol><hr><h3 id="💡-提示" tabindex="-1"><strong>💡 提示</strong> <a class="header-anchor" href="#💡-提示" aria-label="Permalink to &quot;**💡 提示**&quot;">​</a></h3><ul><li>请确保 <code>BEGINPORT</code> 到 <code>ENDPORT</code> 的范围足以容纳 <code>SETVALUE</code> 转换后的二进制位数。</li><li>如果 <code>SETVALUE</code> 超过了端口范围能表示的最大值，高位数据将会被截断。</li></ul>',21)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
